args<-commandArgs(trailingOnly=TRUE)
source("C:/Users/dudup/OneDrive/japan-econometrics-model/src/evaluation/avaliacao_plano/common.R")
source(file.path(root,"src/evaluation/avaliacao_plano/tests.R"))
out<-args[1];repair<-file.path(root,"data/processed/cv_foreign_estavel_20261018")
cfg<-readRDS(file.path(out,"config.rds"));check_package_protocol(cfg)
files<-list.files(file.path(out,"windows"),pattern="[.]rds$",full.names=TRUE)
w<-lapply(files,function(f){x<-readRDS(f);list(scores=x$scores24,diagnostic=x$diagnostic,error=x$error,warnings=x$warnings,seconds=x$elapsed_seconds,file=basename(f))})
scores<-bind_rows(readRDS(file.path(out,"benchmarks.rds")),lapply(w,`[[`,"scores"))
di<-bind_rows(lapply(w,`[[`,"diagnostic"));issues<-map_dfr(w,function(x)tibble(file=x$file,error=if(is.null(x$error))NA_character_ else x$error,warnings=paste(x$warnings,collapse=" | "),seconds=x$seconds))
candidates<-c("BVAR_normal_p3","BVAR_normal_p6","BVAR_condicionado_p3","BVAR_condicionado_p6","bsvarSIGNs_estavel_p3","bsvarSIGNs_estavel_p6")
stopifnot(!anyDuplicated(scores[c("model","fold","variable","h")]),all(is.finite(scores$log_score)),all(is.finite(scores$crps)))
pairs<-bind_rows(expand_grid(variable=alvos,model=c(candidates,"ar","naive","drift")),tibble(variable=c("atividade","cpi_core","juro_curto"),model="var"))
completion<-pairs |> left_join(scores |> group_by(variable,model) |> summarise(cases=n(),origins=n_distinct(fold),.groups="drop"),by=c("variable","model")) |>
 mutate(expected_cases=1028L,expected_origins=47L,complete=coalesce(cases==1028 & origins==47,FALSE))
stopifnot(all(completion$complete),nrow(completion)==57)
actual_check<-scores |> group_by(fold,variable,h) |> summarise(n=n_distinct(actual),.groups="drop");stopifnot(all(actual_check$n==1))
metric<-function(x,...)x |> group_by(...) |> summarise(cases=n(),origins=n_distinct(fold),RMSE=sqrt(mean(squared_error)),MAE=mean(absolute_error),CRPS=mean(crps),LogS=mean(log_score),coverage68=mean(actual>=q16 & actual<=q84),coverage90=mean(actual>=q05 & actual<=q95),width90=mean(q95-q05),.groups="drop")
overall<-metric(scores,variable,model);by_horizon<-metric(scores,variable,model,h)
by_period<-scores |> mutate(period=case_when(date<as.Date("2020-01-01")~"2015-2019",date<as.Date("2022-01-01")~"2020-2021",TRUE~"2022-2026")) |> metric(variable,model,period)
directions<-scores |> arrange(fold) |> group_by(variable,model,h) |> group_modify(~direction_test(.x$actual-.x$origin_value,.x$mean-.x$origin_value,.y$h)) |> ungroup() |>
 group_by(variable) |> mutate(PT_p_holm=p.adjust(PT_p_value,"holm"),PT_HAC_p_holm=p.adjust(PT_HAC_p_value,"holm")) |> ungroup()
bench<-filter(scores,!model%in%candidates) |> select(variable,fold,h,benchmark=model,benchmark_se=squared_error,benchmark_crps=crps,benchmark_logs=log_score)
paired<-filter(scores,model%in%candidates) |> inner_join(bench,by=c("variable","fold","h"),relationship="many-to-many")
dm<-paired |> arrange(fold) |> group_by(variable,model,benchmark,h) |> group_modify(function(.x,.y){
 bind_rows(dm_loss_hac(.x$squared_error,.x$benchmark_se,.y$h) |> mutate(loss="MSE"),
 dm_loss_hac(.x$crps,.x$benchmark_crps,.y$h) |> mutate(loss="CRPS"),dm_loss_hac(.x$log_score,.x$benchmark_logs,.y$h) |> mutate(loss="LogS"))
}) |> ungroup() |> group_by(variable,loss) |> mutate(p_holm=p.adjust(p_value,"holm")) |> ungroup()
quality<-di |> count(family,p,quality,name="windows")
# A comparacao de diagnosticos exclui simultaneamente as mesmas origens de todos os modelos.
badfolds<-di |> filter(quality%in%c("diagnostic_failure","execution_failure")) |> pull(fold) |> unique()
common_good<-scores |> filter(!fold%in%badfolds) |> metric(variable,model)
results<-list(scores=scores,overall=overall,by_horizon=by_horizon,by_period=by_period,directions=directions,dm_tests=dm,diagnostics=di,quality=quality,issues=issues,completion=completion,common_good=common_good)
saveRDS(results,file.path(out,"results.rds"));for(nm in names(results))write_csv(results[[nm]],file.path(out,paste0(nm,".csv")))
# Etapa2 H12: confronto da versao estavel com todos os originais, nos mesmos casos.
old<-readRDS(file.path(root,"data/processed/cv_comparacao_20261017_193604/results.rds"))
rfiles<-list.files(file.path(repair,"windows"),pattern="[.]rds$",full.names=TRUE)
r12<-map_dfr(rfiles,function(f)readRDS(f)$scores12) |> filter(variable%in%c("cpi_core","atividade"))
comparison12<-bind_rows(old$scores,r12) |> metric(variable,model)
write_csv(comparison12,file.path(out,"stage2_comparison_h12.csv"))
log_line("AGREGACAO FINAL CONCLUIDA");print(overall);print(quality)